const SLACK_BLOCKS_PER_MESSAGE = 50;
const SLACK_SECTION_CHARACTERS = 3000;
const SLACK_TABLE_DATA_ROWS = 99;
const SLACK_TABLE_COLUMNS = 20;
const SLACK_TABLE_CHARACTERS = 10000;
const EMPTY_CELL = '—';

type MarkdownSegment = { type: 'text'; text: string } | TableSegment;
type TableSegment = { type: 'table'; headers: string[]; rows: string[][] };

/** Slack refuses empty table cells and tables larger than its row, column and character budgets. */
function createTableBlocks(segment: TableSegment): CardChild[] {
	const headers = toSlackCells(segment.headers.slice(0, SLACK_TABLE_COLUMNS));
	if (headers.length === 0) {
		return [];
	}

	const rows: string[][] = [];
	let characters = countCharacters(headers);
	for (const row of segment.rows) {
		const cells = toSlackCells(normalizeRow(row, headers.length));
		if (rows.length >= SLACK_TABLE_DATA_ROWS || characters + countCharacters(cells) > SLACK_TABLE_CHARACTERS) {
			break;
		}
		characters += countCharacters(cells);
		rows.push(cells);
	}

	const blocks: CardChild[] = [Table({ headers, rows })];
	const hiddenRows = segment.rows.length - rows.length;
	if (hiddenRows > 0) {
		blocks.push(CardText(`_${hiddenRows} more ${pluralize('row', hiddenRows)} — open the chat in nao to see them._`));
	}
	return blocks;
}

function toSlackCells(cells: string[]): string[] {
	return cells.map((cell) => cell.trim() || EMPTY_CELL);
}

function countCharacters(cells: string[]): number {
	return cells.reduce((total, cell) => total + cell.length, 0);
}

function limitSlackBlocks(blocks: CardChild[]): CardChild[] {
	if (blocks.length <= SLACK_BLOCKS_PER_MESSAGE) {
		return blocks;
	}
	const kept = blocks.slice(blocks.length - SLACK_BLOCKS_PER_MESSAGE + 1);
	return [CardText('_The start of this response was trimmed to fit Slack — open the chat in nao to see it._'), ...kept];
}

/** A Slack section block holds a limited number of characters, so long answers are split across blocks. */
function splitLongText(text: string): string[] {
	if (!text) {
		return [];
	}

	const chunks: string[] = [];
	let remaining = text;
	while (remaining.length > SLACK_SECTION_CHARACTERS) {
		const splitIndex = findSplitIndex(remaining);
		chunks.push(remaining.slice(0, splitIndex).trimEnd());
		remaining = remaining.slice(splitIndex).trimStart();
	}
	if (remaining) {
		chunks.push(remaining);
	}
	return chunks.length > 1 ? keepCodeFencesBalanced(chunks) : chunks;
}

function findSplitIndex(text: string): number {
	const window = text.slice(0, SLACK_SECTION_CHARACTERS);
	const breakIndex = Math.max(window.lastIndexOf('\n'), window.lastIndexOf(' '));
	return breakIndex > SLACK_SECTION_CHARACTERS / 2 ? breakIndex : SLACK_SECTION_CHARACTERS;
}

function keepCodeFencesBalanced(chunks: string[]): string[] {
	let insideFence = false;
	return chunks.map((chunk) => {
		const reopened = insideFence ? `\`\`\`\n${chunk}` : chunk;
		insideFence = (reopened.match(/^\s*```/gm)?.length ?? 0) % 2 === 1;
		return insideFence ? `${reopened}\n\`\`\`` : reopened;
	});
}

