	const kept: CardChild[] = [];
	let characters = 0;
	for (const block of [...blocks].reverse()) {
		characters += cardChildToFallbackText(block)?.length ?? 0;
		if (kept.length >= SLACK_BLOCKS_PER_MESSAGE - 1 || characters > SLACK_MESSAGE_CHARACTERS) {
			return [CardText(TRIMMED_RESPONSE_NOTE), ...kept];
		}
		kept.unshift(block);
	}
